        {
            Transform parent=dressing.parent;int sibling=dressing.GetSiblingIndex();var changed=new Dictionary<Renderer,Material[]>();
            try
            {
                dressing.SetParent(null,true);
                foreach(var renderer in world.GetComponentsInChildren<Renderer>(true))if(renderer.sharedMaterials.Contains(stoneTarget)){changed.Add(renderer,renderer.sharedMaterials);renderer.sharedMaterials=renderer.sharedMaterials.Select(m=>m==stoneTarget?stoneSource:m).ToArray();}
